"""matplotlib.font_manager — font management stubs."""


class FontProperties:
    def __init__(self, family=None, style=None, variant=None, weight=None,
                 stretch=None, size=None, fname=None, math_fontfamily=None):
        # Always normalize family to a list (mirrors upstream's behaviour).
        if family is None:
            self._family = ['sans-serif']
        elif isinstance(family, str):
            self._family = [family]
        else:
            self._family = list(family)
        self._style = style or 'normal'
        self._variant = variant or 'normal'
        self._weight = weight or 'normal'
        self._stretch = stretch or 'normal'
        self._size = size if size is not None else 12
        self._fname = fname
        self._math_fontfamily = math_fontfamily

    def get_family(self): return self._family
    def set_family(self, family): self._family = family if isinstance(family, list) else [family]
    def get_style(self): return self._style
    def set_style(self, style): self._style = style
    def get_variant(self): return self._variant
    def set_variant(self, variant): self._variant = variant
    def get_weight(self): return self._weight
    def set_weight(self, weight): self._weight = weight
    def get_stretch(self): return self._stretch
    def set_stretch(self, stretch): self._stretch = stretch
    def get_size(self): return self._size
    def set_size(self, size): self._size = size
    def get_name(self): return self._family[0] if self._family else 'sans-serif'
    def set_name(self, name): self._family = [name]
    def get_file(self): return self._fname
    def set_file(self, fname): self._fname = fname
    def copy(self):
        return FontProperties(
            family=list(self._family), style=self._style, variant=self._variant,
            weight=self._weight, stretch=self._stretch, size=self._size, fname=self._fname
        )


class FontManager:
    def __init__(self, size=None, weight='normal'):
        self.defaultFamily = {'ttf': 'DejaVu Sans', 'afm': 'Helvetica'}
        self.defaultSize = size
        self.defaultWeight = weight
        self.ttflist = []
        self.afmlist = []

    def findfont(self, prop, fontext='ttf', directory=None,
                  fallback_to_default=True, rebuild_if_missing=True):
        """Find a font file matching ``prop``. Walks the system font
        directories — on iOS this returns the path inside the bundled
        font set (or empty string when nothing matches)."""
        import os
        # Resolve the desired family name.
        if isinstance(prop, str):
            wanted = prop.lower()
            size = self.defaultSize or 12
            fnames = [wanted]
        else:
            fnames = [str(f).lower() for f in prop.get_family()]
            size = prop.get_size()
        # Walk ttflist for a name match.
        for entry in self.ttflist:
            entry_name = (getattr(entry, 'name', None) or
                          os.path.splitext(os.path.basename(
                              getattr(entry, 'fname', '')))[0]).lower()
            if any(n in entry_name for n in fnames):
                return getattr(entry, 'fname', '')
        # Fallback: any first available system font.
        if fallback_to_default and self.ttflist:
            return getattr(self.ttflist[0], 'fname', '')
        # As a last resort, look in common iOS/macOS font directories.
        for d in ('/System/Library/Fonts', '/Library/Fonts',
                   os.path.expanduser('~/Library/Fonts')):
            try:
                if not os.path.isdir(d): continue
                for fn in os.listdir(d):
                    if fn.lower().endswith(('.ttf', '.otf', '.ttc')):
                        nm = os.path.splitext(fn)[0].lower()
                        if any(n in nm for n in fnames):
                            return os.path.join(d, fn)
            except OSError:
                pass
        return ''

    def get_default_size(self):
        return self.defaultSize or 12

    def addfont(self, path):
        """Register a font file with the manager."""
        import os
        entry = FontEntry(fname=path,
                          name=os.path.splitext(os.path.basename(path))[0])
        self.ttflist.append(entry)
        return entry


fontManager = FontManager()


def findfont(prop, **kwargs):
    return fontManager.findfont(prop, **kwargs)


def get_font(font_filepaths, hinting_factor=None):
    """Open a font file and return a Font-like wrapper exposing
    ``get_name`` / ``get_path``. Tries Pillow's ImageFont when available
    so callers that probe the font's metadata get real values."""
    import os
    if not font_filepaths:
        return None
    # Accept a single path or a list — take the first existing one.
    if isinstance(font_filepaths, str):
        candidates = [font_filepaths]
    else:
        candidates = list(font_filepaths)
    path = next((p for p in candidates if os.path.isfile(p)), None)
    if path is None:
        return None
    try:
        from PIL import ImageFont
        ttf = ImageFont.truetype(path, size=12)
        # Wrap so caller methods match upstream's Font surface.
        class _PILFontWrap:
            def __init__(self, p, f): self._p = p; self._f = f
            def get_name(self):       return os.path.splitext(os.path.basename(self._p))[0]
            def get_path(self):       return self._p
            def get_size(self):       return self._f.size if self._f else 12
        return _PILFontWrap(path, ttf)
    except Exception:
        # Pillow not available — return a minimal wrapper.
        class _BasicFontWrap:
            def __init__(self, p): self._p = p
            def get_name(self):    return os.path.splitext(os.path.basename(self._p))[0]
            def get_path(self):    return self._p
        return _BasicFontWrap(path)


def findSystemFonts(fontpaths=None, fontext='ttf'):
    """Walk ``fontpaths`` (or the platform's standard font directories)
    and return a list of font-file paths matching ``fontext``."""
    import os
    if fontpaths is None:
        fontpaths = ['/System/Library/Fonts', '/Library/Fonts',
                     os.path.expanduser('~/Library/Fonts'),
                     '/usr/share/fonts', '/usr/local/share/fonts']
    elif isinstance(fontpaths, str):
        fontpaths = [fontpaths]
    exts = get_fontext_synonyms(fontext) if 'get_fontext_synonyms' in globals() \
           else ([fontext] if isinstance(fontext, str) else list(fontext))
    exts = ['.' + e.lstrip('.') for e in exts]
    out = []
    for base in fontpaths:
        if not base or not os.path.isdir(base): continue
        for root, dirs, files in os.walk(base):
            for fn in files:
                if any(fn.lower().endswith(e) for e in exts):
                    out.append(os.path.join(root, fn))
    return out

def FontEntry(fname='', name='', style='normal', variant='normal',
              weight='normal', stretch='normal', size='medium'):
    return type('FontEntry', (), {
        'fname': fname, 'name': name, 'style': style,
        'variant': variant, 'weight': weight, 'stretch': stretch, 'size': size
    })()

# Weight map
weight_dict = {
    'ultralight': 100, 'light': 200, 'normal': 400, 'regular': 400,
    'book': 400, 'medium': 500, 'roman': 500, 'semibold': 600,
    'demibold': 600, 'demi': 600, 'bold': 700, 'heavy': 800,
    'extra bold': 800, 'black': 900,
}


