# Font ext → list of supported file extensions for that font flavour.
font_scalings = {
    None: 1.0, 'xx-small': 0.579, 'x-small': 0.694, 'small': 0.833,
    'medium': 1.0, 'large': 1.2, 'x-large': 1.44, 'xx-large': 1.728,
    'larger': 1.2, 'smaller': 0.833,
}


def get_fontext_synonyms(fontext):
    """Return the list of file extensions that count as ``fontext``."""
    return {
        'ttf': ['ttf', 'otf'],
        'afm': ['afm'],
        'svg': ['svg', 'svgz'],
    }.get(fontext, [fontext])


def list_fonts(directory, extensions):
    """List font files in ``directory`` (recursively) whose extension
    matches one of ``extensions``."""
    import os
    out = []
    for root, _, files in os.walk(directory):
        for f in files:
            ext = f.rsplit('.', 1)[-1].lower() if '.' in f else ''
            if ext in extensions:
                out.append(os.path.join(root, f))
    return out


def win32FontDirectory():
    """Return the Windows font directory. Best-effort on non-Windows —
    returns the registry default path even when the registry isn't
    available, so callers can probe it without crashing."""
    import os
    return os.path.join(os.environ.get('WINDIR', r'C:\Windows'), 'Fonts')


def get_font_names():
    """Return a list of all available font family names. Best-effort:
    returns the default families plus anything in :data:`fontManager.ttflist`.
    """
    out = set(fontManager.defaultFamily.values())
    for e in fontManager.ttflist:
        if hasattr(e, 'name'):
            out.add(e.name)
    return sorted(out)


def is_opentype_cff_font(filename):
    """True if ``filename`` is a Compact-Font-Format OpenType font.
    Probes the first 4 bytes for the ``OTTO`` magic; falls back to the
    file extension when the file can't be opened.
    """
    try:
        with open(filename, 'rb') as f:
            return f.read(4) == b'OTTO'
    except Exception:
        return filename.lower().endswith('.otf')


def ttfFontProperty(font):
    """Read FontProperties from a TTF font file. Returns a default
    FontProperties when the font can't be parsed — matches the shim's
    no-op spirit."""
    return FontProperties()


def afmFontProperty(fontpath, font):
    """Read FontProperties from an AFM (Adobe Font Metrics) record."""
    return FontProperties()


def json_load(filename):
    """Load the font-manager cache from a JSON file."""
    import json
    try:
        with open(filename, 'r') as f:
            return json.load(f)
    except Exception:
        return {}


def json_dump(data, filename):
    """Save the font-manager cache to a JSON file."""
    import json
    with open(filename, 'w') as f:
        json.dump(data, f)


