# ─── Added: FontManager helper methods ──────────────────────────────


def _fm_addfont(self, path):
    """Add a font file to the manager. Stores it in ``ttflist`` so
    findfont() can pick it up."""
    self.ttflist.append(FontEntry(fname=path))

def _fm_get_default_weight(self):   return self.defaultWeight
def _fm_get_font_names(self):
    out = set(self.defaultFamily.values())
    for e in self.ttflist:
        if hasattr(e, 'name'): out.add(e.name)
    return sorted(out)
def _fm_score_family(self, families, family2):
    if isinstance(families, str): families = [families]
    return 0.0 if family2 in families else 1.0
def _fm_score_size(self, size1, size2):
    try: return abs(float(size1) - float(size2)) / 10.0
    except Exception: return 0.0
def _fm_score_style(self, style1, style2):  return 0.0 if style1 == style2 else 0.1
def _fm_score_stretch(self, st1, st2):       return 0.0 if st1 == st2 else 0.1
def _fm_score_variant(self, v1, v2):         return 0.0 if v1 == v2 else 0.1
def _fm_score_weight(self, w1, w2):
    try: return abs(weight_dict.get(w1, 400) - weight_dict.get(w2, 400)) / 1000.0
    except Exception: return 0.0
def _fm_set_default_weight(self, w):  self.defaultWeight = w

FontManager.addfont             = _fm_addfont
FontManager.defaultFont         = property(lambda self: self.defaultFamily.get('ttf'))
FontManager.get_default_weight  = _fm_get_default_weight
FontManager.get_font_names      = _fm_get_font_names
FontManager.score_family        = _fm_score_family
FontManager.score_size          = _fm_score_size
FontManager.score_style         = _fm_score_style
FontManager.score_stretch       = _fm_score_stretch
FontManager.score_variant       = _fm_score_variant
FontManager.score_weight        = _fm_score_weight
FontManager.set_default_weight  = _fm_set_default_weight


# ─── Added: FontProperties methods ──────────────────────────────────


def _fp_get_fontconfig_pattern(self):
    parts = [self._family[0] if self._family else 'sans-serif']
    if self._size:   parts.append(str(self._size))
    if self._weight: parts.append(str(self._weight))
    return ':'.join(parts)
def _fp_set_fontconfig_pattern(self, pattern):
    parts = pattern.split(':')
    if parts: self._family = [parts[0]]
def _fp_get_math_fontfamily(self): return getattr(self, '_math_ff', 'dejavusans')
def _fp_set_math_fontfamily(self, f): self._math_ff = f
def _fp_get_size_in_points(self):
    try: return float(self._size)
    except (TypeError, ValueError): return 10.0
def _fp_get_slant(self):     return self._style
def _fp_set_slant(self, s):  self._style = s

FontProperties.get_fontconfig_pattern = _fp_get_fontconfig_pattern
FontProperties.set_fontconfig_pattern = _fp_set_fontconfig_pattern
FontProperties.get_math_fontfamily    = _fp_get_math_fontfamily
FontProperties.set_math_fontfamily    = _fp_set_math_fontfamily
FontProperties.get_size_in_points     = _fp_get_size_in_points
FontProperties.get_slant              = _fp_get_slant
FontProperties.set_slant              = _fp_set_slant
